const msg = ($json.body?.message || '').toLowerCase();

let provinsi = 'DKI Jakarta';
let kabkota = 'Kota Jakarta';

if (msg.includes('bandung')) { provinsi = 'Jawa Barat'; kabkota = 'Kota Bandung'; }
else if (msg.includes('surabaya')) { provinsi = 'Jawa Timur'; kabkota = 'Kota Surabaya'; }
else if (msg.includes('jogja') || msg.includes('yogyakarta')) { provinsi = 'DI Yogyakarta'; kabkota = 'Kota Yogyakarta'; }
else if (msg.includes('medan')) { provinsi = 'Sumatera Utara'; kabkota = 'Kota Medan'; }
else if (msg.includes('semarang')) { provinsi = 'Jawa Tengah'; kabkota = 'Kota Semarang'; }
else if (msg.includes('makassar')) { provinsi = 'Sulawesi Selatan'; kabkota = 'Kota Makassar'; }
else if (msg.includes('bogor')) { provinsi = 'Jawa Barat'; kabkota = 'Kota Bogor'; }

const now = new Date();
return {
  json: {
    provinsi,
    kabkota,
    bulan: now.getMonth() + 1,
    tahun: now.getFullYear(),
    currentDate: now.getDate()
  }
};

const cityInfo = $('Detect City & Province').first().json;
const data = $json.data || {};
const jadwal = (data.jadwal || []).find(j => j.tanggal === cityInfo.currentDate) || (data.jadwal || [])[0] || {};

let content = `🕌 **Jadwal Shalat Hari Ini - ${cityInfo.kabkota}**\n`;
content += `📍 *Provinsi: ${cityInfo.provinsi}* | 📅 *${jadwal.hari || 'Hari Ini'}, ${jadwal.tanggal_lengkap}*\n\n`;
content += `| Waktu Shalat | Jam (Waktu Lokal) |\n`;
content += `| :--- | :--- |\n`;
content += `| 🌌 **Imsak** | \`${jadwal.imsak || '04:35'}\` |\n`;
content += `| 🌅 **Subuh** | \`${jadwal.subuh || '04:45'}\` |\n`;
content += `| ☀️ **Terbit (Syuruq)** | \`${jadwal.terbit || '06:00'}\` |\n`;
content += `| 🌤️ **Dhuha** | \`${jadwal.dhuha || '06:29'}\` |\n`;
content += `| ☀️ **Dzuhur** | \`${jadwal.dzuhur || '12:03'}\` |\n`;
content += `| ⛅ **Ashar** | \`${jadwal.ashar || '15:24'}\` |\n`;
content += `| 🌇 **Maghrib** | \`${jadwal.maghrib || '17:58'}\` |\n`;
content += `| 🌃 **Isya** | \`${jadwal.isya || '19:09'}\` |\n\n`;
content += `> 💡 *Sumber: Kementerian Agama RI via EQuran.id Shalat API*\n`;

const chips = [
  '📍 Jadwal Shalat Kota Bandung',
  '📍 Jadwal Shalat Kota Surabaya',
  '📍 Jadwal Shalat Kota Yogyakarta',
  '📍 Jadwal Shalat Kota Medan'
];

return { json: { content, chips } };
